    // ---------- Kode pendukung tampilan (boleh disunting) ----------

    private final FasilitasTableModel modelTabel = new FasilitasTableModel();
    private List<model.Fasilitas> dataLengkap = new ArrayList<>();
    private boolean tabelSiap;

    private void siapkanTabel() {
        tabelFasilitas.setModel(modelTabel);
        view.util.UiKit.siapkanTabel(tabelFasilitas);
        tabelFasilitas.setRowHeight(52);

        int[] lebar = {66, 190, 160, 240, 110, 250, 120};
        for (int i = 0; i < lebar.length; i++) {
            tabelFasilitas.getColumnModel().getColumn(i)
                    .setPreferredWidth(lebar[i]);
        }
        tabelFasilitas.getColumnModel().getColumn(0)
                .setCellRenderer(new RendererTabel.Id());
        tabelFasilitas.getColumnModel().getColumn(1)
                .setCellRenderer(new RendererTabel.Utama());
        tabelFasilitas.getColumnModel().getColumn(2)
                .setCellRenderer(new RendererTabel.TeksRedup());
        tabelFasilitas.getColumnModel().getColumn(3)
                .setCellRenderer(new RendererTabel.TeksRedup());
        tabelFasilitas.getColumnModel().getColumn(4)
                .setCellRenderer(new RendererTabel.Lencana());
        tabelFasilitas.getColumnModel().getColumn(5)
                .setCellRenderer(new RendererTabel.TeksRedup());
        tabelFasilitas.getColumnModel().getColumn(6)
                .setCellRenderer(new RendererTabel.Aksi("Ubah", "Hapus"));

        tabelFasilitas.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e) {
                int baris = tabelFasilitas.rowAtPoint(e.getPoint());
                int kolom = tabelFasilitas.columnAtPoint(e.getPoint());
                if (baris < 0 || kolom != 6
                        || baris >= modelTabel.getRowCount()) {
                    return;
                }
                int geser = e.getX()
                        - tabelFasilitas.getCellRect(baris, kolom, true).x;
                model.Fasilitas f = modelTabel.get(baris);
                if (geser < 56) {
                    bukaForm(f);
                } else {
                    hapus(f);
                }
            }
        });

        txtCari.getDocument().addDocumentListener(
                new javax.swing.event.DocumentListener() {
            @Override
            public void insertUpdate(javax.swing.event.DocumentEvent e) {
                saring();
            }

            @Override
            public void removeUpdate(javax.swing.event.DocumentEvent e) {
                saring();
            }

            @Override
            public void changedUpdate(javax.swing.event.DocumentEvent e) {
                saring();
            }
        });

        tombolTambah.addActionListener(e -> bukaForm(null));
    }

    @Override
    public String judul() {
        return "Kelola Fasilitas";
    }

    @Override
    public void muatData() {
        if (!tabelSiap) {
            tabelSiap = true;
            siapkanTabel();
        }
        dataLengkap = new dao.FasilitasDAO().getAllFasilitas();
        tampilkan(dataLengkap);
    }

    private void tampilkan(List<model.Fasilitas> daftar) {
        modelTabel.setData(daftar);
        lblJumlah.setText("Menampilkan " + daftar.size() + " dari "
                + dataLengkap.size() + " fasilitas");
    }

    private void saring() {
        String kunci = txtCari.getText().trim().toLowerCase();
        if (kunci.isEmpty()) {
            tampilkan(dataLengkap);
            return;
        }
        List<model.Fasilitas> hasil = new ArrayList<>();
        for (model.Fasilitas f : dataLengkap) {
            String gabung = (f.getNamaFasilitas() + " " + f.getJenisFasilitas()
                    + " " + f.getLokasi()).toLowerCase();
            if (gabung.contains(kunci)) {
                hasil.add(f);
            }
        }
        tampilkan(hasil);
    }

    private void bukaForm(model.Fasilitas f) {
        java.awt.Window jendela
                = javax.swing.SwingUtilities.getWindowAncestor(this);
        if (jendela instanceof MainFrame) {
            ((MainFrame) jendela).bukaForm(
                    f == null ? "Tambah Fasilitas" : "Ubah Fasilitas",
                    new FormFasilitas(f));
        }
    }

    private void hapus(model.Fasilitas f) {
        int pilih = javax.swing.JOptionPane.showConfirmDialog(this,
                "Fasilitas " + f.getNamaFasilitas() + " akan dihapus permanen."
                + " Tindakan ini tidak dapat dibatalkan.",
                "Hapus fasilitas?", javax.swing.JOptionPane.YES_NO_OPTION,
                javax.swing.JOptionPane.WARNING_MESSAGE);
        if (pilih != javax.swing.JOptionPane.YES_OPTION) {
            return;
        }
        if (!new dao.FasilitasDAO().hapusFasilitas(f.getIdFasilitas())) {
            javax.swing.JOptionPane.showMessageDialog(this,
                    "Fasilitas ini memiliki riwayat laporan kerusakan "
                    + "sehingga tidak dapat dihapus.", "Fasilitas tidak dapat "
                    + "dihapus", javax.swing.JOptionPane.ERROR_MESSAGE);
        }
        muatData();
    }

    @Override
    public void sesuaikanUkuran(int lebar, int tinggi) {
        int isi = Math.max(600, lebar - 68);
        txtCari.setBounds(34, 96, Math.min(420, isi - 250), 38);
        tombolTambah.setBounds(34 + isi - 200, 96, 200, 38);
        int tinggiKartu = Math.max(260, tinggi - 226);
        panelTabel.setBounds(34, 152, isi, tinggiKartu);
        scrollFasilitas.setBounds(22, 18, isi - 44, tinggiKartu - 36);
        tabelFasilitas.setBounds(0, 0, isi - 44, tinggiKartu - 36);
        lblJumlah.setBounds(34, 152 + tinggiKartu + 10, 600, 18);
    }
